D.Quests[11336]={Title=S[11783],Objectives="在奥特兰克山谷战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。",Description=S[952],CompletionLog=S[4467],Completion=S[15007],Progress=S[6007]}
D.Quests[11337]={Title=S[11788],Objectives=S[7652],Description="与部落的战斗永远都不会结束，$n。即使在外域，领土的争夺和往日的仇恨也足够引起新的战争。$B$B进入风暴之眼吧，相信联盟在外域也会像在艾泽拉斯那样所向披靡。",CompletionLog=S[4467],Completion=S[11523],Progress=S[6007]}
