D.Quests[11923]={Title="接火炬",Objectives="连续接住火炬4次，然后与食焰大师谈一谈。",Description=S[11950],CompletionLog=S[4505],Completion="你有被烧到吗?假如你被烧到的话，也许下次玩火的时候可要三思一下……$B$B开玩笑的啦!你做的很好!你获得了正式的肯定。你已经是一位正式的火焰杂耍师了。现在你可以去好好地玩得开心了!",Progress="接火炬是非常有趣的活动，你不这么觉得吗?但要小心!你不会想被烧伤的!"}
D.Quests[11924]={Title="继续接火炬",Objectives="连续接住火炬10次，然后与吞火大师谈一谈。",Description=S[12461],CompletionLog=S[4393],Completion=S[11493]}
